messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Red vs Blue Race</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #87CEEB; }
        canvas { display: block; }
    </style>
</head>
<body>
    <script type="module">
        import * as THREE from './three.module.js';

        // Configuration
        const TRACK_LENGTH = 200;
        const FINISH_LINE_Z = 0;
        const START_LINE_Z = -TRACK_LENGTH;
        const LANE_WIDTH = 4;

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky blue
        scene.fog = new THREE.Fog(0x87CEEB, 20, 150);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 500);
        camera.position.set(0, 15, 25);
        camera.lookAt(0, 0, -20);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
        dirLight.position.set(50, 100, 50);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 2048;
        dirLight.shadow.mapSize.height = 2048;
        dirLight.shadow.camera.near = 0.5;
        dirLight.shadow.camera.far = 500;
        dirLight.shadow.camera.left = -50;
        dirLight.shadow.camera.right = 50;
        dirLight.shadow.camera.top = 50;
        dirLight.shadow.camera.bottom = -50;
        scene.add(dirLight);

        // Environment
        // Ground
        const groundGeo = new THREE.PlaneGeometry(500, 500);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x3a9d23 });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.position.y = -0.1;
        ground.receiveShadow = true;
        scene.add(ground);

        // Track
        const trackGeo = new THREE.PlaneGeometry(20, 500);
        const trackMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
        const track = new THREE.Mesh(trackGeo, trackMat);
        track.rotation.x = -Math.PI / 2;
        track.receiveShadow = true;
        scene.add(track);

        // Finish Line
        const finishGeo = new THREE.PlaneGeometry(20, 2);
        const finishMat = new THREE.MeshStandardMaterial({ color: 0xffffff });
        const finishLine = new THREE.Mesh(finishGeo, finishMat);
        finishLine.rotation.x = -Math.PI / 2;
        finishLine.position.set(0, 0.01, FINISH_LINE_Z);
        finishLine.receiveShadow = true;
        scene.add(finishLine);

        // Checkered pattern for finish line
        for(let x = -10; x < 10; x+=2) {
            const checkGeo = new THREE.PlaneGeometry(2, 2);
            const checkMat = new THREE.MeshStandardMaterial({ color: 0x000000 });
            const check = new THREE.Mesh(checkGeo, checkMat);
            check.rotation.x = -Math.PI / 2;
            check.position.set(x + 1, 0.02, FINISH_LINE_Z);
            scene.add(check);
        }

        // Car Factory
        function createCar(colorHex) {
            const carGroup = new THREE.Group();

            // Body
            const bodyGeo = new THREE.BoxGeometry(2, 0.8, 4);
            const bodyMat = new THREE.MeshStandardMaterial({ color: colorHex });
            const body = new THREE.Mesh(bodyGeo, bodyMat);
            body.position.y = 0.8;
            body.castShadow = true;
            carGroup.add(body);

            // Cabin
            const cabinGeo = new THREE.BoxGeometry(1.8, 0.6, 2);
            const cabinMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
            const cabin = new THREE.Mesh(cabinGeo, cabinMat);
            cabin.position.set(0, 1.4, -0.2);
            cabin.castShadow = true;
            carGroup.add(cabin);

            // Wheels
            const wheelGeo = new THREE.CylinderGeometry(0.4, 0.4, 0.4, 16);
            const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111 });

            const positions = [
                { x: -1.1, z: 1.2 }, { x: 1.1, z: 1.2 },
                { x: -1.1, z: -1.2 }, { x: 1.1, z: -1.2 }
            ];

            positions.forEach(pos => {
                const wheel = new THREE.Mesh(wheelGeo, wheelMat);
                wheel.rotation.z = Math.PI / 2;
                wheel.position.set(pos.x, 0.4, pos.z);
                wheel.castShadow = true;
                carGroup.add(wheel);
            });

            // Spoiler
            const spoilerGeo = new THREE.BoxGeometry(2, 0.1, 0.5);
            const spoilerMat = new THREE.MeshStandardMaterial({ color: colorHex });
            const spoiler = new THREE.Mesh(spoilerGeo, spoilerMat);
            spoiler.position.set(0, 1.6, -1.8);
            carGroup.add(spoiler);

            const spoilerStandGeo = new THREE.BoxGeometry(0.1, 0.3, 0.1);
            const stand1 = new THREE.Mesh(spoilerStandGeo, spoilerMat);
            stand1.position.set(-0.8, 1.45, -1.8);
            carGroup.add(stand1);
            const stand2 = new THREE.Mesh(spoilerStandGeo, spoilerMat);
            stand2.position.set(0.8, 1.45, -1.8);
            carGroup.add(stand2);

            return carGroup;
        }

        const blueCar = createCar(0x0000FF);
        const redCar = createCar(0xFF0000);

        // Initial positions
        blueCar.position.set(-LANE_WIDTH, 0, START_LINE_Z);
        redCar.position.set(LANE_WIDTH, 0, START_LINE_Z);

        scene.add(blueCar);
        scene.add(redCar);

        // Race Logic
        let raceTime = 0;
        const RACE_DURATION = 10; // seconds
        const SPEED_BASE = 20; // units per second

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);

            // Update Race Time
            raceTime += 0.016; // approx 60fps

            // Calculate Positions
            // Blue car: Linear speed
            const blueProgress = raceTime / RACE_DURATION;
            const blueZ = START_LINE_Z + (TRACK_LENGTH * blueProgress);

            // Red car: Starts slower, accelerates, overtakes
            // Using a curve: 0 -> 1 over time, but slower at start
            // Easing function: easeOutCubic for acceleration effect
            // We want Red to be behind initially, then overtake.
            // Let's use a custom logic:
            // Red speed = Base * (0.5 + 0.8 * (time/duration)^2)
            // This makes red start at 0.5 speed and end at 1.3 speed

            const redSpeedFactor = 0.5 + 0.8 * Math.pow(raceTime / RACE_DURATION, 2);
            const redDistance = SPEED_BASE * redSpeedFactor * raceTime;
            const redZ = START_LINE_Z + redDistance;

            // Update Car Positions
            blueCar.position.z = blueZ;
            redCar.position.z = redZ;

            // Update Camera to follow cars
            // Camera Z should be ahead of the cars
            const cameraZ = Math.max(blueZ, redZ) + 20;
            camera.position.z = cameraZ;
            camera.position.x = 0; // Center track
            camera.position.y = 15; // Height
            camera.lookAt(0, 0, Math.max(blueZ, redZ) - 10);

            // Check for finish
            if (redZ >= FINISH_LINE_Z) {
                // Reset Race
                raceTime = 0;
                blueCar.position.z = START_LINE_Z;
                redCar.position.z = START_LINE_Z;
            }

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
```
